import sqlite3

from langchain.tools import tool


@tool
def reassign_claim_handler(claim_id: str, new_adjuster_id: str) -> str:
    """Reassign a claim to another adjuster."""
    if not claim_id or not claim_id.startswith("CLM-"):
        return "Error: invalid claim_id"
    if not new_adjuster_id.strip():
        return "Error: new_adjuster_id is required"
    conn = sqlite3.connect("claims.db")
    adjuster = conn.execute(
        "SELECT active FROM adjusters WHERE adjuster_id = ?", (new_adjuster_id,)
    ).fetchone()
    if adjuster is None or not adjuster[0]:
        conn.close()
        return "Error: adjuster not found or inactive"
    cur = conn.execute(
        "UPDATE claims SET adjuster_id = ? WHERE claim_id = ?", (new_adjuster_id, claim_id)
    )
    conn.commit()
    conn.close()
    return "Reassigned" if cur.rowcount else "Error: claim not found"
